        W  := 0.45;
        include 'Figures\Scripts\Deltoidal Icositetrahedron_Coordinates.inc';

        pillow := sqrt(2) - 1/3;
        for i := 0 to 23 do begin
            Cx[i] := Cx[i] * pillow;
            Cy[i] := Cy[i] * pillow;
            Cz[i] := Cz[i] * pillow;
        end;

        D1 := (Cx[0] + Cy[0] + Cz[0]) / sqrt(3);
        D2 := Cz[0];




        K  := 0.45;

        C0 := K * (4 + sqrt(2)) / 7;
        C1 := K * sqrt(2);
        A1 := K * (6 + sqrt(2)) / 17;
        A2 := A1 * (sqrt(2) + 1);

        f := sqrt(2) - 1/3;
        W1 := A1 * f;
        W2 := A2 * f;

